import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 7 Bats","description":"学习 关系从句中的指代与功能说明，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 7 Bats","description":"学习 关系从句中的指代与功能说明，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 关系从句中的指代与功能说明，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 6 The sporting spirit","link":"/life/english/new-concept/book-4/unit-01/lesson-006"},"next":{"text":"第四册：流利英语 · Lesson 8 Trading standards","link":"/life/english/new-concept/book-4/unit-01/lesson-008"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 6 The sporting spirit","link":"/life/english/new-concept/book-4/unit-01/lesson-006"},"next":{"text":"第四册：流利英语 · Lesson 8 Trading standards","link":"/life/english/new-concept/book-4/unit-01/lesson-008"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-01/lesson-007.md","filePath":"life/english/new-concept/book-4/unit-01/lesson-007.md"}'),s={name:"life/english/new-concept/book-4/unit-01/lesson-007.md"};function i(l,e,r,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-lesson-7-bats" tabindex="-1">第四册：流利英语 · Lesson 7 Bats <a class="header-anchor" href="#第四册-流利英语-·-lesson-7-bats" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 7 Bats&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从蝙蝠感知周围环境的说明进入机制阅读，学习把信号发出、返回和处理的步骤按顺序说清楚。避免从一种感知方式推出“蝙蝠完全看不见”等错误概括。重点是使用指代清晰的关系从句，说明结构与功能之间的联系，并区分机制解释与推测。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>echo</td><td>/ˈekəʊ/</td><td>n.</td><td>回声</td><td>a returning echo</td></tr><tr><td>signal</td><td>/ˈsɪɡnəl/</td><td>n.</td><td>信号</td><td>send a signal</td></tr><tr><td>detect</td><td>/dɪˈtekt/</td><td>v.</td><td>探测</td><td>detect an obstacle</td></tr><tr><td>distance</td><td>/ˈdɪstəns/</td><td>n.</td><td>距离</td><td>estimate distance</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>bounce back — 反射回来</li><li>depend on — 取决于；依靠</li></ul><h2 id="语法讲解-关系从句中的指代与功能说明" tabindex="-1">语法讲解：关系从句中的指代与功能说明 <a class="header-anchor" href="#语法讲解-关系从句中的指代与功能说明" aria-label="Permalink to &quot;语法讲解：关系从句中的指代与功能说明&quot;">​</a></h2><p>which 可以指物，who 指人；限制性关系从句帮助确定是哪一个对象，非限制性关系从句用逗号补充信息。The echoes that return first provide one clue. 中 that return first 限定 echoes。关系代词作主语时不能省略；作宾语时在限制性从句中通常可省。写机制说明时要让 which 紧靠明确先行词，避免读者不知它指声音、动物还是整个过程。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The device measures the delay between a signal and the echo that returns from the wall.</p></blockquote><p>这个装置测量信号与墙壁返回的回声之间的时间差。</p><p>that returns from the wall 修饰 echo，that 在从句作主语，不能省略。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>不能把 the echo that returns 写成 the echo returns 后仍接在原宾语位置；省略主语关系词会破坏结构。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读时连读 signal and the echo；在 that returns 内不停顿，避免把限制性关系从句误读为额外一句。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>A speaker sends a short pulse towards a wall. A sensor records the echo that comes back. The delay helps the device estimate the distance.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句解释一个回声测距演示，包括发射、返回和估算三个步骤。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>步骤顺序清楚；关系从句确定返回的信号，delay 把前两步与计算联系起来。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例中 that 指 signal 还是 echo？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> echo</p><p><strong>解析：</strong> 关系从句紧接并限定 echo。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>that returns 中 that 可以省略吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不可以。</p><p><strong>解析：</strong> that 是关系从句的主语。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>合并：The sensor receives a signal. The signal comes from the ceiling.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The sensor receives a signal that comes from the ceiling.</p><p><strong>解析：</strong> that 引导限制性关系从句修饰 signal。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：关系从句中的指代与功能说明。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-006">上一课</a> · <a href="/life/english/new-concept/book-4/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-01/lesson-008">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(s,[["render",i]]);export{u as __pageData,b as default};
